import { decorateTemplateWidgets } from "./decorate";
import type { Board, Widget, WidgetStyle, WidgetType } from "./types";

/** Shape of one entry in spec/templates.json (generated by scripts/sync-templates.mjs). */
export interface NormalizedWidget {
  z: number;
  id: string;
  type: string;
  x: number;
  y: number;
  width: number;
  height: number;
  parentId: string | null;
  relativeTo?: string;
  sourceRelativeTo?: string;
  fillColor?: string;
  cardTheme?: string;
  strokeColor?: string;
  fontSize?: number;
  fontFamily?: string;
  color?: string;
  title?: string;
  content?: string;
}

export interface NormalizedTemplate {
  source?: { url: string; capturedAt: string; widgetCount: number };
  types: Record<string, number>;
  widgets: NormalizedWidget[];
}

export const TEMPLATE_KEYS = [
  "user-story-map-basic",
  "product-roadmap-basic",
  "product-roadmap-basic-prefilled",
  "kanban-framework",
] as const;

export type TemplateKey = (typeof TEMPLATE_KEYS)[number];

export const TEMPLATE_LABELS: Record<TemplateKey, string> = {
  "user-story-map-basic": "User Story Map",
  "product-roadmap-basic": "Product Roadmap",
  "product-roadmap-basic-prefilled": "Roadmap (pre-filled)",
  "kanban-framework": "Kanban Framework",
};

const HTML_ENTITIES: Record<string, string> = {
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&nbsp;": " ",
};

/** Miro stores rich text as HTML; the canvas renders plain text. */
export function stripHtml(html: string | undefined): string {
  if (!html) return "";
  return html
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&[a-z#0-9]+;/gi, (entity) => HTML_ENTITIES[entity.toLowerCase()] ?? entity)
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function style(w: NormalizedWidget): WidgetStyle | undefined {
  const s: WidgetStyle = {};
  if (w.fillColor) s.fillColor = w.fillColor;
  if (w.cardTheme) s.cardTheme = w.cardTheme;
  if (w.strokeColor) s.strokeColor = w.strokeColor;
  if (w.fontSize) s.fontSize = w.fontSize;
  if (w.fontFamily) s.fontFamily = w.fontFamily;
  if (w.color) s.color = w.color;
  return Object.keys(s).length ? s : undefined;
}

export function toBoard(key: TemplateKey, template: NormalizedTemplate): Board {
  const widgets: Widget[] = template.widgets.map((w) => ({
    id: w.id,
    type: w.type as WidgetType,
    // Cards inside a kanban have no coordinates of their own: the kanban layout
    // engine owns their position (ADR-006).
    x: w.x ?? 0,
    y: w.y ?? 0,
    width: w.width,
    height: w.height,
    parentId: w.parentId,
    content: stripHtml(w.content) || undefined,
    title: stripHtml(w.title) || undefined,
    style: style(w),
  }));

  return {
    id: key,
    title: TEMPLATE_LABELS[key],
    // Stickers, legends and lane labels carry no content in the source API, so
    // modelled defaults are filled in here, once, on the way into the document.
    widgets: decorateTemplateWidgets(key, widgets),
  };
}

export function bounds(widgets: Widget[]) {
  if (!widgets.length) return { x: 0, y: 0, width: 1, height: 1 };
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const w of widgets) {
    minX = Math.min(minX, w.x - w.width / 2);
    minY = Math.min(minY, w.y - w.height / 2);
    maxX = Math.max(maxX, w.x + w.width / 2);
    maxY = Math.max(maxY, w.y + w.height / 2);
  }
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
}
